```json
{
  "root_causes": [
    {
      "service": "rate",
      "fault_kind": "network_delay",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT s.service_name AS caller, c.service_name AS callee, count(*) n, approx_quantile(s.duration,0.5)/1e6 client_median_ms, approx_quantile(c.duration,0.5)/1e6 server_median_ms, approx_quantile(epoch(c.time)-epoch(s.time),0.5) server_start_lag_s FROM abnormal_traces s JOIN abnormal_traces c ON c.parent_span_id=s.span_id AND c.trace_id=s.trace_id WHERE s.service_name='search' AND s.span_name='rate.Rate/GetRates' GROUP BY 1,2",
          "claim": "search's rate.Rate/GetRates client span takes about 1,609 ms, but rate's server span takes about 0.1 ms and starts about 1.6 s later."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'normal' per, service_name, span_name, count(*) n, approx_quantile(duration,0.5)/1e6 median_ms FROM normal_traces WHERE service_name='search' AND span_name='rate.Rate/GetRates' GROUP BY 1,2,3 UNION ALL SELECT 'abnormal', service_name, span_name, count(*), approx_quantile(duration,0.5)/1e6 FROM abnormal_traces WHERE service_name='search' AND span_name='rate.Rate/GetRates' GROUP BY 1,2,3",
          "claim": "Median search-to-rate call time rose from about 1.7 ms in normal period to about 1,609 ms in the incident."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, approx_quantile(duration,0.5)/1e6 median_ms, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='rate' GROUP BY 1,2",
          "claim": "rate's own server spans stay fast in the incident (p95 about 0.8 ms), so the delay is not inside rate.",
        },
        {
          "kind": "metric",
          "sql": "SELECT 'normal' per, service_name, avg(value) cpu FROM normal_metrics WHERE service_name IN ('search','rate') AND metric='container.cpu.usage' GROUP BY 1,2 UNION ALL SELECT 'abnormal', service_name, avg(value) FROM abnormal_metrics WHERE service_name IN ('search','rate') AND metric='container.cpu.usage' GROUP BY 1,2",
          "claim": "search and rate CPU usage fell during the incident, so neither service is CPU-saturated and the delay is not resource exhaustion."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "rate",
      "to": "search",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT s.service_name caller, s.span_name caller_span, c.service_name callee, c.span_name callee_span, count(*) n, approx_quantile(s.duration,0.5)/1e6 caller_median_ms, approx_quantile(c.duration,0.5)/1e6 callee_median_ms FROM abnormal_traces s JOIN abnormal_traces c ON c.parent_span_id=s.span_id AND c.trace_id=s.trace_id WHERE s.service_name='search' AND s.span_name='search.Search/Nearby' AND c.span_name='rate.Rate/GetRates' GROUP BY 1,2,3,4",
          "claim": "search.Search/Nearby is about 1,609 ms and its child rate.Rate/GetRates call is about 1,609 ms, so the delay sits in the rate call."
        }
      ]
    },
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT s.service_name, s.span_name, c.service_name child_svc, c.span_name child_span, count(*) n, approx_quantile(s.duration,0.5)/1e6 parent_median_ms, approx_quantile(c.duration,0.5)/1e6 child_median_ms FROM abnormal_traces s JOIN abnormal_traces c ON c.parent_span_id=s.span_id AND c.trace_id=s.trace_id WHERE s.service_name='frontend' AND s.span_name='HTTP /hotels' AND c.span_name='search.Search/Nearby' GROUP BY 1,2,3,4",
          "claim": "frontend HTTP /hotels takes about 1,612 ms and its search.Search/Nearby child takes about 1,610 ms, so the search delay drives user-facing latency."
        }
      ]
    }
  ]
}
